import { test, expect } from '@playwright/test';

test.describe('Table List Badge Count', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table-list');
  });

  test('should display badge count when rows are selected', async ({ page }) => {
    const firstRowCheckbox = page.getByRole('checkbox', { name: 'Select Row 1' });
    const secondRowCheckbox = page.getByRole('checkbox', { name: 'Select Row 2' });
    const badgeCount = page.getByText('Selected Rows:');

    await firstRowCheckbox.check();
    await secondRowCheckbox.check();

    await expect(badgeCount).toHaveText('Selected Rows: 2');
  });

  test('should update badge count when a row is deselected', async ({ page }) => {
    const firstRowCheckbox = page.getByRole('checkbox', { name: 'Select Row 1' });
    const badgeCount = page.getByText('Selected Rows:');

    await firstRowCheckbox.check();
    await expect(badgeCount).toHaveText('Selected Rows: 1');

    await firstRowCheckbox.uncheck();
    await expect(badgeCount).toHaveText('Selected Rows: 0');
  });
});
